 onPredictionComplete = { result ->
 Toast.makeText(context, "AI identified: ${result.breedName}", Toast.LENGTH_LONG).show()
 },
 onBreedFound = { breed ->
 selectedBreed = breed
 previousScreen = currentScreen
 currentScreen = "dog_detail"
 }
 )
 }

 else -> HomeScreen(
 onNavigate = { route -> 
 previousScreen = currentScreen
 currentScreen = route 
 },
 onBreedClick = { breed ->
 selectedBreed = breed
 previousScreen = currentScreen
 currentScreen = "dog_detail"
 },
